DECLARE @no varchar(31)=?,@name nvarchar(642)=?,@kana nvarchar(74)=?,@year smallint=?,@grade varchar(2)=?,@class bigint=?,@unassigned bit=?,@prefecture varchar(2)=?,@phone varchar(16)=?,@from date=?,@to date=?,@s1 varchar(2)=?,@s2 varchar(2)=?,@s3 varchar(2)=?,@s4 varchar(2)=?; SELECT COUNT_BIG(*) FROM (SELECT TOP (10001) s.student_id FROM dbo.m_student s LEFT JOIN dbo.m_class c ON c.class_id=s.class_id WHERE s.is_deleted=0 AND (@no IS NULL OR s.student_no LIKE @no ESCAPE '!') AND (@name IS NULL OR s.name_key LIKE @name ESCAPE '!') AND (@kana IS NULL OR s.kana_key LIKE @kana ESCAPE '!') AND (@year IS NULL OR c.school_year=@year) AND (@grade IS NULL OR c.grade_code=@grade) AND (@class IS NULL OR s.class_id=@class) AND (@unassigned=0 OR s.class_id IS NULL) AND (@prefecture IS NULL OR s.prefecture_code=@prefecture) AND (@phone IS NULL OR s.phone_number=@phone OR s.emergency_phone_number=@phone) AND (@from IS NULL OR s.admission_date>=@from) AND (@to IS NULL OR s.admission_date<=@to) AND ((@s1 IS NULL AND @s2 IS NULL AND @s3 IS NULL AND @s4 IS NULL) OR s.enrollment_status_code IN (@s1,@s2,@s3,@s4))) limited;
